const TEST_BAD_FEED = false; // set true ONLY to test feed-failure handling

const q = (query) =>
  `https://news.google.com/rss/search?q=${query}+when:7d&hl=id&gl=ID&ceid=ID:id`;

const feeds = [
  { id: 'gn-market', name: 'Google News - Pasar Properti', url: q('pasar+properti+indonesia') },
  { id: 'gn-kpr',    name: 'Google News - KPR',            url: q('KPR+suku+bunga+rumah') },
  { id: 'gn-policy', name: 'Google News - Kebijakan',      url: q('FLPP+OR+Tapera+OR+subsidi+rumah+OR+%223+juta+rumah%22') },
  { id: 'gn-first',  name: 'Google News - Rumah Pertama',  url: q('tips+beli+rumah+pertama') },
  { id: 'gn-price',  name: 'Google News - Harga Rumah',    url: q('harga+rumah+properti+indonesia') },
  { id: 'gn-infra',  name: 'Google News - Infrastruktur',  url: q('infrastruktur+kawasan+hunian') },
];

if (TEST_BAD_FEED) {
  feeds.push({ id: 'bad', name: 'Deliberately Broken', url: 'https://invalid.example.invalid/rss.xml' });
}

return feeds.map(f => ({ json: f }));

const items = $input.all();
const stats = { raw: items.length, feed_errors: 0, missing_fields: 0 };
const out = [];

const stripHtml = (s) => String(s || '')
  .replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();

const titleKey = (t) => t.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 80);

const hash = (s) => {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h.toString(16).padStart(8, '0');
};

for (const it of items) {
  const j = it.json;
  if (j.error) { stats.feed_errors++; continue; }

  const rawTitle = stripHtml(j.title);
  const url = String(j.link || j.guid || '').trim();
  if (!rawTitle || !url) { stats.missing_fields++; continue; }

  let title = rawTitle;
  let source = '';
  const m = rawTitle.match(/^(.*)\s-\s([^-]+)$/);
  if (m && url.includes('news.google.com')) { title = m[1].trim(); source = m[2].trim(); }
  if (!source) { try { source = new URL(url).hostname.replace(/^www\./, ''); } catch (e) { source = 'Unknown'; } }

  const d = new Date(j.isoDate || j.pubDate || '');
  const published_at = isNaN(d.getTime()) ? null : d.toISOString();

  let description = stripHtml(j.contentSnippet || j.content || j.description || j.summary);
  if (description.toLowerCase().startsWith(title.toLowerCase().slice(0, 30))) description = '';

  const key = titleKey(title);
  out.push({ json: {
    article_id: hash(key),
    title, url, source, published_at,
    description: description.slice(0, 600),
    title_key: key,
    collected_at: new Date().toISOString(),
  }});
}

out.forEach(o => { o.json._stats = stats; });
return out.length ? out : [{ json: { _stats: stats, _empty: true } }];

const MAX_AGE_DAYS = 7;
const MIN_SCORE = 2;
const now = Date.now();

const INCLUDE = ['properti','rumah','hunian','perumahan','apartemen','kpr','flpp','tapera',
  'real estate','rusun','kavling','suku bunga','bank tanah','pengembang','developer',
  'subsidi','kredit pemilikan','landed house','harga rumah','sewa rumah','kawasan hunian'];

const EXCLUDE = ['rumah sakit','rumah tangga','rumah makan','rumah ibadah','togel','judi',
  'zodiak','ramalan','lowongan kerja','prediksi skor','tanah longsor','banjir bandang'];

const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (text, kw) => new RegExp('\\b' + esc(kw) + '\\b').test(text);

return $input.all().map(({ json: a }) => {
  if (a._empty) return { json: { ...a, keep: false, drop_reason: 'no_articles' } };

  let drop_reason = null;

  if (!a.published_at) {
    drop_reason = 'missing_date';
  } else {
    const ageDays = (now - new Date(a.published_at).getTime()) / 86400000;
    if (ageDays > MAX_AGE_DAYS) drop_reason = 'too_old';
    else if (ageDays < -1) drop_reason = 'future_date';
  }

  const title = a.title.toLowerCase();
  const desc = (a.description || '').toLowerCase();

  if (!drop_reason) {
    const bad = EXCLUDE.find(k => has(title, k) || has(desc, k));
    if (bad) drop_reason = 'excluded_keyword:' + bad;
  }

  let score = 0; const matched = [];
  if (!drop_reason) {
    for (const k of INCLUDE) {
      if (has(title, k)) { score += 2; matched.push(k); }
      else if (has(desc, k)) { score += 1; matched.push(k); }
    }
    if (score < MIN_SCORE) drop_reason = 'irrelevant';
  }

  return { json: { ...a, relevance_score: score, matched_keywords: matched,
                   keep: !drop_reason, drop_reason } };
});

const seenUrl = new Set();
const seenTitle = new Set();
const out = [];

const sorted = $input.all().sort((a, b) =>
  new Date(b.json.published_at) - new Date(a.json.published_at));

for (const it of sorted) {
  const { url, title_key } = it.json;
  if (seenUrl.has(url) || seenTitle.has(title_key)) continue;
  seenUrl.add(url); seenTitle.add(title_key);
  out.push(it);
}
return out;

const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };

const normalized = safeAll('Normalize Articles');
const stats = (normalized[0] && normalized[0].json._stats) || {};
const filtered = safeAll('Filter Recent & Relevant');
const afterInRun = safeAll('Dedup In-Run');
const finalItems = $input.all().filter(i => i.json.article_id);

const dropReasons = {};
filtered.filter(i => !i.json.keep).forEach(i => {
  const r = String(i.json.drop_reason).split(':')[0];
  dropReasons[r] = (dropReasons[r] || 0) + 1;
});

const kept = filtered.filter(i => i.json.keep).length;

const summary = {
  run_at: new Date().toISOString(),
  feeds_attempted: safeAll('Feed List').length,
  raw_items: stats.raw ?? 0,
  feed_errors: stats.feed_errors ?? 0,
  missing_fields: stats.missing_fields ?? 0,
  dropped_by_reason: dropReasons,
  kept_after_filter: kept,
  removed_in_run_duplicates: kept - afterInRun.length,
  removed_cross_run_duplicates: afterInRun.length - finalItems.length,
  new_articles: finalItems.length,
  status: finalItems.length ? 'OK' : 'NO_NEW_ARTICLES',
};

return [{ json: { summary, articles: finalItems.map(i => i.json) } }];
